library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity psd_capture_controller is

    generic
    (
        DATA_WIDTH   : integer := 32;
        SAMPLE_COUNT : integer := 2048
    );

    port
    (
        clk  : in std_logic;
        rstn : in std_logic;

        ----------------------------------------------------
        -- Capture command from PS / Register Controller
        ----------------------------------------------------

        psd_capture_start : in std_logic;

        ----------------------------------------------------
        -- Generated by FFT/PSD block
        ----------------------------------------------------

        NbPSD_DataValid : in std_logic;

        ----------------------------------------------------
        -- High while BRAM is being read
        ----------------------------------------------------

        MemBusy : out std_logic;

        ----------------------------------------------------
        -- BRAM Port B
        ----------------------------------------------------

        bram_rd_addr : out std_logic_vector(10 downto 0);
        bram_rd_data : in  std_logic_vector(DATA_WIDTH-1 downto 0);

        ----------------------------------------------------
        -- AXI-Stream output
        ----------------------------------------------------

        m_axis_tdata  : out std_logic_vector(DATA_WIDTH-1 downto 0);
        m_axis_tvalid : out std_logic;
        m_axis_tready : in  std_logic;
        m_axis_tlast  : out std_logic;

        ----------------------------------------------------
        -- Status
        ----------------------------------------------------

        psd_capture_start_status : out std_logic;
        capture_done : out std_logic
    );

end entity;


architecture rtl of psd_capture_controller is

    type state_type is
    (
        IDLE,
        READ_WAIT,
        READ_DATA
    );

    signal state : state_type;

    signal rd_addr : unsigned(10 downto 0);

    signal sample_counter : unsigned(11 downto 0);

    signal data_reg : std_logic_vector(DATA_WIDTH-1 downto 0);

    signal output_valid : std_logic;
    signal psd_capture_start_Sync : std_logic;

    signal psd_capture_start_prev : std_logic;
    signal psd_capture_start_Flag : std_logic;




COMPONENT psd_capture_start_sync_core is
    Port (
        clk        : in  std_logic;
        reset      : in  std_logic;
        lock_async : in  std_logic;
        lock_sync  : out std_logic
    );
end COMPONENT;

begin


  Inst_psd_capture_start_Lock_Sync : psd_capture_start_sync_core
    port map (
        clk        => clk,
        reset      => rstn,
        lock_async => psd_capture_start,
        lock_sync  => psd_capture_start_Sync
    );
    
      
process (clk,rstn)
begin  
    if rstn = '0' then
        psd_capture_start_prev       <= '0';
        psd_capture_start_Flag       <= '0';
        psd_capture_start_status     <= '0';
    elsif (rising_edge(clk)) then
        psd_capture_start_prev <= psd_capture_start_Sync;
        if(psd_capture_start_prev = '0' and  psd_capture_start_Sync = '1') then
            psd_capture_start_Flag   <= '1';
            psd_capture_start_status <= '1';
        end if;        
        if(state = READ_DATA) then
            psd_capture_start_Flag   <= '0';
            psd_capture_start_status <= '0';
        end if;          
   end if;
end process;    

    --------------------------------------------------------
    -- BRAM address
    --------------------------------------------------------

    bram_rd_addr <= std_logic_vector(rd_addr);


    --------------------------------------------------------
    -- AXI-Stream
    --------------------------------------------------------

    m_axis_tdata  <= data_reg;

    m_axis_tvalid <= output_valid;


    --------------------------------------------------------
    -- TLAST
    --------------------------------------------------------

    m_axis_tlast <= '1'
        when
        (
            output_valid = '1' and
            sample_counter = SAMPLE_COUNT-1
        )
        else '0';


    --------------------------------------------------------
    -- Memory Busy
    --------------------------------------------------------

    MemBusy <= '1'
        when
        (
            state = READ_WAIT or
            state = READ_DATA
        )
        else '0';


    --------------------------------------------------------
    -- Main FSM
    --------------------------------------------------------

    process(clk)

    begin

        if rising_edge(clk) then

            if rstn = '0' then

                state <= IDLE;

                rd_addr <= (others => '0');

                sample_counter <= (others => '0');

                data_reg <= (others => '0');

                output_valid <= '0';

                capture_done <= '0';

                psd_capture_start_prev <= '0';


            else

                ------------------------------------------------
                -- Defaults
                ------------------------------------------------

                capture_done <= '0';

--                psd_capture_start_prev <= psd_capture_start;


                case state is


                    ------------------------------------------------
                    -- IDLE
                    ------------------------------------------------

                    when IDLE =>

                        output_valid <= '0';

                        rd_addr <= (others => '0');

                        sample_counter <= (others => '0');


                        ------------------------------------------------
                        -- Rising edge of capture_start
                        -- AND PSD data is ready
                        ------------------------------------------------

--                        if
--                        (
--                            psd_capture_start_prev = '0' and
--                            psd_capture_start = '1' and
--                            NbPSD_DataValid = '1'
--                        )
                        if
                        (
                            psd_capture_start_Flag = '1' and
                            NbPSD_DataValid = '1'
                        )
                        then

                            rd_addr <= (others => '0');

                            sample_counter <= (others => '0');

                            state <= READ_WAIT;

                        end if;


                    ------------------------------------------------
                    -- Wait for BRAM read latency
                    ------------------------------------------------

                    when READ_WAIT =>

                        data_reg <= bram_rd_data;

                        output_valid <= '1';

                        state <= READ_DATA;


                    ------------------------------------------------
                    -- AXI Stream transfer
                    ------------------------------------------------

                    when READ_DATA =>

                        if output_valid = '1' then

                            if m_axis_tready = '1' then


                                ------------------------------------------------
                                -- Last sample
                                ------------------------------------------------

                                if sample_counter = SAMPLE_COUNT-1 then

                                    output_valid <= '0';

                                    capture_done <= '1';

                                    rd_addr <= (others => '0');

                                    sample_counter <= (others => '0');

                                    state <= IDLE;


                                ------------------------------------------------
                                -- Next sample
                                ------------------------------------------------

                                else

                                    sample_counter <= sample_counter + 1;

                                    rd_addr <= rd_addr + 1;

                                    output_valid <= '0';

                                    state <= READ_WAIT;

                                end if;

                            end if;

                        end if;


                    when others =>

                        state <= IDLE;

                        output_valid <= '0';

                        rd_addr <= (others => '0');

                        sample_counter <= (others => '0');

                end case;

            end if;

        end if;

    end process;

end architecture;
